        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hcp_prod_8433_fhc_loader') }}
    where (nullif(trim(PD_PARTNER_ID),'')) is not null
    union all
    select
        md5(upper('HUB_DISTRIBUTION_CHANNEL|' || (HUB_DISTRIBUTION_CHANNEL_BK__PD_PARTNER_ID))) as HUB_DISTRIBUTION_CHANNEL_HK
        , PD_PARTNER_TYPE as CHANNEL_TYPE
        , PD_SUB_IMD_CODE as SUB_CHANNEL_CODE
        , cast(null as varchar) as CHANNEL_CATEGORY
        , cast(null as varchar) as CHANNEL_NAME
        , 'BA_HCP_PROD_8439_CLH_LOADER' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hcp_prod_8439_clh_loader') }}
    where (nullif(trim(PD_PARTNER_ID),'')) is not null
    union all
    select
        md5(upper('HUB_DISTRIBUTION_CHANNEL|' || (HUB_DISTRIBUTION_CHANNEL_BK__PARTNER_ID))) as HUB_DISTRIBUTION_CHANNEL_HK
        , PARTNER_TYPE as CHANNEL_TYPE
        , cast(null as varchar) as SUB_CHANNEL_CODE
        , ISSUANCE_SOURCE as CHANNEL_CATEGORY
        , LG_NAME as CHANNEL_NAME
        , 'BJAZ_BANDHAN_MEDI_CLAM' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_bandhan_medi_clam') }}
    where (nullif(trim(PARTNER_ID),'')) is not null
    union all
    select
        md5(upper('HUB_DISTRIBUTION_CHANNEL|' || (HUB_DISTRIBUTION_CHANNEL_BK__PARTNER_ID))) as HUB_DISTRIBUTION_CHANNEL_HK
        , PARTNER_TYPE as CHANNEL_TYPE
