resolved as (
    select
        HUB_DISTRIBUTION_CHANNEL_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then CHANNEL_TYPE end) as CHANNEL_TYPE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then SUB_CHANNEL_CODE end) as SUB_CHANNEL_CODE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then CHANNEL_CATEGORY end) as CHANNEL_CATEGORY,
        coalesce(max(case when SOURCE_RUN = 'opus_health_legacy_v4' then CHANNEL_NAME end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then CHANNEL_NAME end)) as CHANNEL_NAME,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_DISTRIBUTION_CHANNEL_HK
),

hashed as (
    select
        *,
        case when CHANNEL_TYPE is not null or SUB_CHANNEL_CODE is not null or CHANNEL_CATEGORY is not null or CHANNEL_NAME is not null
                     then md5(upper(coalesce(cast(CHANNEL_TYPE as varchar), '') || '|' || coalesce(cast(SUB_CHANNEL_CODE as varchar), '') || '|' || coalesce(cast(CHANNEL_CATEGORY as varchar), '') || '|' || coalesce(cast(CHANNEL_NAME as varchar), '')))
                end as SAT_CHANNEL_DEFINITION_HASHDIFF
    from resolved
)

select * from hashed
where HUB_DISTRIBUTION_CHANNEL_HK is not null
  and SAT_CHANNEL_DEFINITION_HASHDIFF is not null
